            return true;
        }
        if (
            metadataMode != StreamFinalityDomains.METADATA_MODE_ONCHAIN
                && metadataMode != StreamFinalityDomains.METADATA_MODE_HYBRID
        ) return false;
        return metadataReads.latestCollectionSnapshotHash(collectionId) != bytes32(0);
